package com.worklink.controller;import com.worklink.dto.proposal.*;import com.worklink.service.ProposalService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController public class ProposalController {final ProposalService s;public ProposalController(ProposalService x){s=x;}@PostMapping("/api/projects/{id}/proposals")@PreAuthorize("hasRole('FREELANCER')")ResponseEntity<ProposalResponse> create(@PathVariable Long id,@Valid @RequestBody ProposalRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(id,r));}@GetMapping("/api/freelancer/proposals")@PreAuthorize("hasRole('FREELANCER')")List<ProposalResponse> mine(){return s.mine();}@GetMapping("/api/freelancer/proposals/{id}")@PreAuthorize("hasRole('FREELANCER')")ProposalResponse mine(@PathVariable Long id){return s.mine(id);}@PatchMapping("/api/freelancer/proposals/{id}/withdraw")@PreAuthorize("hasRole('FREELANCER')")ProposalResponse withdraw(@PathVariable Long id){return s.withdraw(id);}@GetMapping("/api/client/projects/{p}/proposals")@PreAuthorize("hasRole('CLIENT')")List<ProposalResponse> project(@PathVariable Long p){return s.project(p);}@GetMapping("/api/client/projects/{p}/proposals/{id}")@PreAuthorize("hasRole('CLIENT')")ProposalResponse one(@PathVariable Long p,@PathVariable Long id){return s.project(p,id);}@PatchMapping("/api/client/projects/{p}/proposals/{id}/status")@PreAuthorize("hasRole('CLIENT')")ProposalResponse status(@PathVariable Long p,@PathVariable Long id,@Valid @RequestBody ProposalStatusRequest r){return s.status(p,id,r);}}
